-- 由 scripts/gen_seed.py 產生，請勿手改；改資料請改 catalog-v1.json 或直接在系統內維護
-- 產生日期：2026-08-25

on conflict (id) do update set name=excluded.name, publisher=excluded.publisher,
  url=excluded.url, note=excluded.note, kind=excluded.kind;

on conflict (id) do nothing;

on conflict (id) do update set name=excluded.name, section_title=excluded.section_title;

on conflict (id) do update set multiplier=excluded.multiplier, legal_basis=excluded.legal_basis;

on conflict (key) do nothing;

on conflict (id) do update set std_price=excluded.std_price, unit=excluded.unit,
  evidence_id=excluded.evidence_id, evidence_note=excluded.evidence_note,
  index_id=excluded.index_id, index_coeff=excluded.index_coeff,
  needs_area=excluded.needs_area, active=excluded.active;
